/* Generated by services/_build.py from services/_faq.py. The AI assistant uses it as its fallback knowledge. */
window.HC_FAQ = [{"q": "How do I book an appointment at Hot Cut?", "a": "Book online around the clock, or call +45 97 12 60 60. If you want a cut and colour on the same day, book early so we can set aside enough time."}, {"q": "Why can’t I see available times before choosing a treatment?", "a": "Because treatments take very different amounts of time. A men’s cut, a colour and extensions each need their own space in the calendar. Once you have chosen your treatment, the booking system only shows times with room for the whole treatment."}, {"q": "Why do I need to log in to book?", "a": "The first time, you register with your mobile number. The system then remembers what you had last time and how long it took, so next time you can book the same again in a few clicks. If you need something else, just choose another treatment. If you prefer, call us on +45 97 12 60 60."}, {"q": "Can I book online outside opening hours?", "a": "Yes. Online booking is open around the clock, including evenings and weekends when the salon is closed."}, {"q": "How do I move or cancel my appointment?", "a": "Call +45 97 12 60 60 or email info@hotcut.dk as early as possible. That way we can offer the slot to someone else and find you a new time."}, {"q": "Can I get an appointment the same day?", "a": "Check available times in the online booking, or call +45 97 12 60 60 and we will help you find the first free slot."}, {"q": "How far in advance should I book?", "a": "For a regular cut you can often get a time soon. For larger colour treatments, extensions and updos for weddings or confirmations we recommend booking well ahead, especially in the busy spring and summer season."}, {"q": "Can I book for several people at once?", "a": "Yes. Call +45 97 12 60 60 and we will find times that fit together, for example for a parent and child or for a bride and bridesmaids."}, {"q": "Can I get a free consultation before booking?", "a": "Yes. You are always welcome to drop in for a no-obligation chat, and extensions always start with a free consultation where you get a fixed price."}, {"q": "What does a women's cut cost at Hot Cut in Herning?", "a": "A women's cut including wash and blow-dry costs DKK {{p:dameklip}}. A fringe costs DKK {{p:pandehaar}}, and a luxury treatment with scalp massage can be added for DKK {{p:haarkur}}."}, {"q": "What does a men's cut cost?", "a": "A men's cut costs DKK {{p:herreklip}}. A men's cut “krans” costs DKK {{p:herreklip_krans}}, a clipper cut DKK {{p:maskinklip}} and a beard trim DKK {{p:skaeg}}."}, {"q": "Why does a women's cut cost more than a men's cut?", "a": "A women's cut usually takes longer, needs more detailed technique and more thorough styling. The price includes wash and blow-dry."}, {"q": "What does it cost to colour my hair?", "a": "Full colour costs DKK {{p:helfarve_kort}} on short hair, DKK {{p:helfarve_mellem}} on medium-length hair and DKK {{p:helfarve_lang}} on long hair. Root colour costs DKK {{p:bundfarve}} (DKK {{p:bundfarve_lang}} on long hair). Colour on medium-length and long hair includes Olaplex."}, {"q": "What do highlights cost?", "a": "Foil highlights cost DKK {{p:refl_stanniol_kort}} on short hair, DKK {{p:refl_stanniol_mellem}} on medium-length and DKK {{p:refl_stanniol_lang}} on long hair. Highlights along the parting cost DKK {{p:refl_skilning}}, cap highlights DKK {{p:refl_haette}}, and full colour with highlights DKK {{p:helfarve_refl_kort}}–{{p:helfarve_refl_lang}}."}, {"q": "Do the prices include VAT?", "a": "Yes. All prices include VAT."}, {"q": "Do you charge for advice?", "a": "No. Advice is free and part of every treatment."}, {"q": "Do I get advice before you start?", "a": "Yes, always and free of charge. We start from your face shape, hair type and style, and you are welcome to bring inspiration photos."}, {"q": "How often should I have my hair cut?", "a": "Generally every 6 to 8 weeks. If you have long hair and want to keep the length, you can wait up to 12 weeks. A fade often needs touching up a little more often."}, {"q": "Can you cut curly and wavy hair?", "a": "Yes. We adapt the cut to your natural fall, whether your hair is straight, wavy or curly, so it looks good both styled and natural."}, {"q": "How do I know whether short or long hair suits me?", "a": "It depends on your face shape, your hair texture and how much time you want to spend styling. We help you choose based on your style and routine."}, {"q": "Can I bring a photo of the style I want?", "a": "Yes, please do. A photo is a good starting point, and we adapt the look to your hair so it also works at home."}, {"q": "Do you wash and blow-dry with a women's cut?", "a": "Yes. A women's cut includes wash and blow-dry, and we show you how to style your hair yourself."}, {"q": "What is the luxury hair treatment?", "a": "A nourishing hair treatment with a scalp massage that you can add when you have a cut. It costs DKK {{p:haarkur}}."}, {"q": "Do you trim fringes separately?", "a": "Yes. A fringe costs DKK {{p:pandehaar}}."}, {"q": "Which men's cuts do you do?", "a": "Everything from a classic side parting and crew cut to fades, textured crops and undercuts. Right now skin fades, mid fades and the classic slick back are among the most popular."}, {"q": "Which men's style suits my face?", "a": "A fade or crew cut adds definition to a round face, while a classic side parting or longer hair with texture often suits a square face. With fine hair, a short cut makes it look fuller."}, {"q": "Do you trim beards?", "a": "Yes. A beard trim costs DKK {{p:skaeg}} and can be booked with a men's cut. We trim it to suit your face shape and haircut."}, {"q": "Can men have colour?", "a": "Yes. We offer a quick 10-minute colour for men at DKK {{p:farve_herre}}, as well as regular colour treatments."}, {"q": "Do you cut children's hair, and what does it cost?", "a": "Yes. Children's cuts cost DKK {{p:boern_0_3}} (age 0–3) and DKK {{p:boern_4_8}} (age 4–8). Girls' cuts age 9–12 cost DKK {{p:pigeklip}} and boys' cuts age 9–12 DKK {{p:drengeklip}}."}, {"q": "Do you cut women, men and children?", "a": "Yes. Everyone is welcome, whatever their gender, age or style."}, {"q": "What does balayage cost at Hot Cut?", "a": "Balayage costs DKK {{p:balayage}}, or DKK {{p:balayage_toning}} with toning, both including Olaplex."}, {"q": "What is balayage?", "a": "A colour technique where the hair is lightened with soft transitions so the colour blends into your own shade. It gives a natural, sun-kissed look and softer regrowth."}, {"q": "What is the difference between balayage and babylights?", "a": "Balayage gives soft, natural colour with less visible regrowth. Babylights are very fine light strands for a brighter, more detailed effect. Babylights cost DKK {{p:babylights}} (DKK {{p:babylights_toning}} with toning)."}, {"q": "What is the difference between root colour, full colour and highlights?", "a": "Root colour covers only the regrowth at the scalp. Full colour gives an even colour all over. Highlights lighten or darken selected strands to add depth and movement."}, {"q": "What is toning, and do I need it?", "a": "Toning adjusts the shade after lightening, so the result is cooler, warmer, more beige or more natural. Whether you need it depends on your hair and the shade you want."}, {"q": "How long does a colour treatment take?", "a": "It depends on the treatment and the length, thickness and starting point of your hair. Balayage usually takes longer than a standard colour. Call us if you need an exact time."}, {"q": "How often should I have my hair coloured?", "a": "It depends on the technique. Full or root colour usually needs refreshing when regrowth shows, while balayage and soft highlights grow out more gently and can last longer between visits. We advise you on what suits your hair."}, {"q": "Can you cover grey hair?", "a": "Yes. Grey hair can be covered with root or full colour, or blended with highlights so the regrowth shows less. We find the right solution together."}, {"q": "Which hair colour do you use?", "a": "We colour with idHAIR, a Danish professional colour brand: Hair Paint (permanent colour), Gloss (a demi-permanent toner for tone and shine) and Colour Bomb (a colour conditioner for between visits)."}, {"q": "What is Olaplex, and is it included?", "a": "Olaplex rebuilds the bonds in hair that colouring, heat and sun break down. It is included in colour on medium-length and long hair, and in balayage and babylights."}, {"q": "Can I have a cut and colour in the same visit?", "a": "Yes. Many clients combine a women's cut with colour, balayage or highlights. Book early so we can set aside the time needed."}, {"q": "What are the hair colour trends for 2026?", "a": "Warm blondes, copper and soft blends. Sharp stripes and cool ash tones take a step back. Read more in our blog post on hair colours for 2026."}, {"q": "What if I have reacted to hair colour before?", "a": "Tell us when you book or call, so the stylist can talk it through with you before the treatment. If you are unsure about an allergy, ask your doctor."}, {"q": "Do you offer keratin treatments, and what do they cost?", "a": "Yes. A keratin treatment costs DKK {{p:keratin_mellem}} on medium-length hair and DKK {{p:keratin_lang}} on long hair."}, {"q": "Do you do perms?", "a": "Yes. A perm including a cut costs DKK {{p:perm_kort}} on short hair, DKK {{p:perm_mellem}} on medium-length and DKK {{p:perm_lang}} on long hair."}, {"q": "How do I best look after coloured hair?", "a": "Use shampoo and conditioner for coloured hair, protect it from heat and drying out, and follow your stylist's advice on refreshing the colour. A colour conditioner such as idHAIR Colour Bomb keeps the colour fresh between visits."}, {"q": "What can I do about damaged or dry hair?", "a": "Trim the ends regularly, use heat protection and give your hair a treatment. Olaplex No.3 is a treatment that rebuilds the hair, and we are happy to advise on the right care. A hair and scalp analysis can show what your hair needs."}, {"q": "How do I avoid yellow tones in blonde hair?", "a": "Use a purple toning shampoo such as Olaplex No.4P Blonde Enhancer, which removes yellow and brassy tones. Toning in the salon can also adjust the shade."}, {"q": "Should I use heat protection?", "a": "Yes, whenever you use a hairdryer, straighteners or curling tongs. It protects your hair from drying out and damage."}, {"q": "What do extensions cost at Hot Cut?", "a": "Extensions start from DKK {{p:extensions}}. The price depends on the amount and length, and you get a fixed price at a free consultation."}, {"q": "Which extensions do you use?", "a": "We use Hairtalk tape extensions made of 100% real Remy hair, in lengths from 25 to 55 cm. The bonds lie flat against the head and no heat is used to fit them."}, {"q": "How long do tape extensions last?", "a": "Tape extensions usually need moving up after 6 to 8 weeks as your own hair grows. The extension hair itself can often be reused several times if cared for properly."}, {"q": "Can tape extensions damage my own hair?", "a": "Not when they are fitted and maintained correctly. Too much extra hair, badly placed bonds or moving up too late can strain the hair, which is why we assess your hair first."}, {"q": "Do extensions suit fine hair?", "a": "Yes, tape extensions can also be used in fine hair because they are ultra-thin. The amount and placement must suit your own hair, which we assess at the consultation."}, {"q": "How do I care for my extensions?", "a": "Brush gently, use extension-friendly products, put conditioner and oil on the lengths rather than the bonds, and dry the hair thoroughly around the bonds after washing."}, {"q": "Can I style and colour my extensions?", "a": "You can style them with a hairdryer, straighteners and curling tongs if you use heat protection and avoid direct heat on the bonds. Hairtalk advises against permanent colouring and lightening, so we find the right shade before fitting."}, {"q": "Do you have extensions I can take out myself?", "a": "Yes. The Hairtalk Hairband is real hair on an invisible elastic band with no glue, tape or clips. It takes under five minutes to put on and you take it off yourself. Clip-on extensions are another option."}, {"q": "Do you do updos for weddings and confirmations?", "a": "Yes. A bridal updo costs DKK {{p:brudeopsaetning}}, a confirmation updo DKK {{p:konfirmation}} and an updo DKK {{p:opsaetning_lille}} or DKK {{p:opsaetning_stor}}."}, {"q": "Should I have a trial before the wedding?", "a": "We recommend it. A trial updo costs DKK {{p:proeveopsaetning}}, and we find the look together before the big day."}, {"q": "When should I book an updo for a wedding or confirmation?", "a": "Well in advance, especially if the day falls in the busy spring or summer season. Book the trial at the same time."}, {"q": "What should I bring to a trial updo?", "a": "Photos of the dress, accessories and your inspiration. If you have hair accessories or flowers, bring them along."}, {"q": "Can I have make-up on the same day as my updo?", "a": "Yes. Make-up costs DKK {{p:makeup_lille}} or DKK {{p:makeup_stor}} and can be combined with your updo so hair and make-up work together."}, {"q": "Can the groom have his hair cut with you too?", "a": "Yes. The groom can have a men's cut (DKK {{p:herreklip}}) and a beard trim (DKK {{p:skaeg}}). A cut one to two weeks before the wedding gives it time to settle."}, {"q": "What are the wedding hairstyles for 2026?", "a": "Softer updos, loose tendrils, glossy waves and fresh flowers. Grooms are moving from stiff wax to natural texture. Read more in our blog post on wedding hairstyles for 2026."}, {"q": "Do you tint and shape brows and lashes?", "a": "Yes. Brow shaping (wax or tweezers) costs DKK {{p:bryn_rettet}}, brow tint DKK {{p:bryn_farvet}}, lash tint DKK {{p:vipper_farvet}}, and the package with brows and lashes tinted and shaped costs DKK {{p:bryn_vipper_pakke}}."}, {"q": "Do you offer brow lamination?", "a": "Yes. Brow lift/lamination costs DKK {{p:browlam}} without tint and DKK {{p:browlam_farve}} with tint."}, {"q": "Do you offer lash lifts?", "a": "Yes, we also offer lash lifts. Call +45 97 12 60 60 for the price."}, {"q": "What does make-up cost?", "a": "Make-up costs DKK {{p:makeup_lille}} (light) or DKK {{p:makeup_stor}} (full)."}, {"q": "Do you sell lash and brow serum?", "a": "Yes. We stock Sanzi Beauty, a Danish brand with lash and brow serum, mascara, lip products and powder. First results from the lash serum usually show after 6 to 8 weeks."}, {"q": "What is a hair and scalp analysis?", "a": "With our analysis equipment we look closely at your scalp and hair strands. A handheld camera with strong magnification shows them on a screen so you can see for yourself. The stylist then explains what we see and gives you concrete advice."}, {"q": "What does a hair analysis cost?", "a": "A hair and scalp analysis costs DKK {{p:analyse}}. If you buy products for DKK {{p:analyse_graense}}, the DKK {{p:analyse}} is deducted, which works out as a {{p:analyse_rabat_pct}}% discount on the products."}, {"q": "Who benefits from a hair analysis?", "a": "Anyone unsure which products and care their hair and scalp need, for example with dry, oily or damaged hair."}, {"q": "Can the analysis be combined with a cut?", "a": "Yes. You can have the analysis as part of your next visit."}, {"q": "Is the hair analysis a medical examination?", "a": "No. The analysis gives advice on care and products. If you have hair loss, itching or other symptoms that worry you, talk to your doctor."}, {"q": "Which brands do you use and sell?", "a": "Olaplex, Roze Avenue, Sanzi Beauty, Hairtalk, ghd and idHAIR."}, {"q": "Which Olaplex products do you stock?", "a": "Including No.3 Hair Perfector (treatment), No.4 Bond Maintenance shampoo, No.4P Blonde Enhancer for blonde hair, No.4C clarifying shampoo and the oil. Ask in the salon which suits your hair."}, {"q": "Do you sell straighteners and hairdryers?", "a": "Yes. We have ghd styling tools on the product wall in the salon and are happy to help you choose the right one for your hair."}, {"q": "What is Roze Avenue?", "a": "A Nordic hair and beauty brand created by stylists. With us you will find dry shampoo, the Luxury Restore Masq hair mask and the Glow Collection self-tan, among others."}, {"q": "Can I buy products without an appointment?", "a": "Yes, you are welcome to drop by during opening hours and get advice on the products."}, {"q": "How can I get a discount on products?", "a": "Have a hair and scalp analysis for DKK {{p:analyse}}. If you buy products for DKK {{p:analyse_graense}}, the DKK {{p:analyse}} is deducted."}, {"q": "Where is Hot Cut in Herning?", "a": "At Søndergade 12, 7400 Herning, in the town centre. It is easy to combine your visit with a stroll down the high street."}, {"q": "What are your opening hours?", "a": "Monday 09:00–15:00, Tuesday, Wednesday and Friday 08:30–17:00, and Thursday 08:30–19:00. Closed Saturday and Sunday. Online booking is open around the clock."}, {"q": "Are you open in the evening?", "a": "On Thursdays we are open until 19:00. Other weekdays we close at 17:00, and on Mondays at 15:00."}, {"q": "Where can I park?", "a": "There is kerbside parking along Søndergade, the street you drive along to the salon, and a large car park just around the corner by Herning Library and the cinema. The station's underground car park is also a few minutes away. See the map on the contact page, and check the signs for time limits."}, {"q": "How do I contact you?", "a": "Call +45 97 12 60 60, email info@hotcut.dk, or message us on Instagram @hotcutherning or Facebook."}, {"q": "Who are the stylists at Hot Cut?", "a": "Heidi Møller (stylist and owner), Anna Sand Daasbjerg and Karina Andreasen. Clients especially praise being remembered from visit to visit."}, {"q": "What do clients say about Hot Cut?", "a": "Hot Cut is rated 4.6 stars from 69 reviews on Google. Clients especially mention friendly service, honest advice and being remembered."}, {"q": "What if I'm not happy with the result?", "a": "Contact us as soon as possible on +45 97 12 60 60 or at info@hotcut.dk, and we will find a solution together."}, {"q": "What can the AI assistant help with?", "a": "It answers questions around the clock about prices, treatments, opening hours, extensions, colour, products and the hair analysis, in Danish and English. You can also ask by voice."}, {"q": "Can the AI assistant book an appointment for me?", "a": "No. It cannot see the calendar, so booking happens online or by phone on +45 97 12 60 60."}, {"q": "Do you store what I write to the AI assistant?", "a": "No. The assistant runs in your browser and your questions are not sent to us. Read more in our privacy policy."}, {"q": "Is the website available in English?", "a": "Yes. The whole website is in Danish and English. Switch language with DA/EN at the top of the page."}];
window.HC_PARK = [{"n": "P1", "t": "Along Søndergade", "d": "Kerbside parking on Søndergade, the street you drive along to the salon. The closest option.", "m": 0, "lat": 56.13535, "lon": 8.97599}, {"n": "P2", "t": "Large car park by the library", "d": "The large car park just around the corner, between Herning Library and the cinema.", "m": 1, "lat": 56.13504, "lon": 8.97693}, {"n": "P3", "t": "Car park by the cinema", "d": "By the Bio City / Nordisk Film cinema, a few minutes on foot.", "m": 2, "lat": 56.13351, "lon": 8.9771}, {"n": "P4", "t": "Station car park (underground)", "d": "Covered underground car park with about 137 spaces. Handy when it rains.", "m": 2, "lat": 56.13365, "lon": 8.97622}];
